// ==== HUD futurista ====
// Siempre visible. CEJAS ARRIBA -> barrido de escaner por la cara.  OJOS MUY ABIERTOS -> el visor da un pulso (laser).
// AJUSTES
var SON_ESCANER = "", SON_LASER = "";   // mp3 opcionales ("" = sonido sintetizado "scifi" / "laser")
var scan = -1, flash = 0;

function play(url, name) { if (!window.folio) return; if (url) window.folio.sfx.fileOr(url, name); else window.folio.sfx.play(name); }
function browRaise() { scan = 0; play(SON_ESCANER, "scifi"); }
function eyesWide() { flash = 1; play(SON_LASER, "laser"); }

function update(event) {
	var d = event.delta / 1000, t = event.time / 1000;
	var rings = this.getObjectByName("anillos"), small = this.getObjectByName("anillo_pequeno"), visor = this.getObjectByName("visor"), sc = this.getObjectByName("escaner");
	rings.rotation.z = -t * 0.6; small.rotation.z = t * 1.4;
	visor.material.opacity = 0.9 + Math.sin(t * 3) * 0.1;
	flash = Math.max(0, flash - d * 2.2);
	var f = 1 + Math.sin(flash * Math.PI) * 0.18; visor.scale.set(-f, f, 1);
	if (scan >= 0) { scan += d / 0.9; sc.visible = scan < 1; sc.position.y = 0.5 - scan * 1.3; if (scan >= 1) scan = -1; }
}
